"""PostgreSQL engine, session factory and the declarative Base every model uses."""

from sqlalchemy import MetaData, create_engine
from sqlalchemy.orm import DeclarativeBase, sessionmaker

from app.config import settings

# Stable constraint names, so Alembic migrations (and 409 messages) refer to the same
# name on every machine instead of names generated by PostgreSQL.
NAMING_CONVENTION = {
    "ix": "ix_%(table_name)s_%(column_0_N_name)s",
    "uq": "uq_%(table_name)s_%(column_0_N_name)s",
    "ck": "ck_%(table_name)s_%(constraint_name)s",
    "fk": "fk_%(table_name)s_%(column_0_name)s_%(referred_table_name)s",
    "pk": "pk_%(table_name)s",
}


class Base(DeclarativeBase):
    metadata = MetaData(naming_convention=NAMING_CONVENTION)


# pool_size + max_overflow = 80 connections: the 60 simultaneous requests of the
# concurrency test each get their own connection instead of waiting in a queue
# (PostgreSQL's default max_connections is 100).
# pool_pre_ping: drop connections that died (e.g. postgres restarted) before using them.
engine = create_engine(
    settings.database_url,
    pool_size=20,
    max_overflow=60,
    pool_pre_ping=True,
    connect_args={"connect_timeout": 3},
)

# Usage in services, one transaction per request:
#     with SessionLocal() as session, session.begin():
#         ...
# expire_on_commit=False: objects stay readable after the commit (to build the response).
SessionLocal = sessionmaker(engine, expire_on_commit=False)
